import groovy.json.JsonSlurper
import java.io.File
import java.security.MessageDigest

plugins { id("com.android.library") }

// Independent Android 15 guest userland. The prepared tree is generated by
// scripts/prepare-a15.py in this module; -PguestRuntimeA15Prepared=<dir>
// overrides it. Everything the guest needs at runtime (rootfs, prepared assets,
// jniLibs) is produced here, and .gitignore keeps the multi-GB images out of the
// repository.
//
// This module is deliberately independent of :guest-runtime-a9. The two share a
// contract (the manifest schema and the host-side launcher), not binaries: an
// API 28 libc can never load an API 35 libart, and vice versa.
// 2026-11-11：APK 消费的是 **prepared-apk**（由 rom/stage-apk-payload.py 产出），
// 不是 prepared/。区别只有一处、但很关键：客体 .so 在 prepared-apk 里是
// assets/guest-runtime-a15/lib/**（清单 files[].libPath），**不在 jniLibs/**，
// 所以 APK 的 lib/arm64-v8a 只剩宿主侧那两个库（桌面渲染器 + p1 客户端）。
// 判据见 docs/rom-package/04 §4：unzip -l app-debug.apk 里不应再有客体 .so。
val preparedRoot: File? = providers.gradleProperty("guestRuntimeA15Prepared").orNull
    ?.let { file(it) }
val bundledRoot = projectDir.resolve("prepared-apk")
val runtimeRoot = preparedRoot ?: bundledRoot

android {
    namespace = "io.a10vm.guestruntime.a15"
    compileSdk = 37
    compileSdkMinor = 0
    defaultConfig { minSdk = 28 }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    // 目录注入移到下面的 androidComponents 块（AGP 9 的 sourceSets 库路径会抛
    // ClassCastException: DefaultAndroidLibrarySourceSet -> AndroidLibrarySourceSet）。
}

fun sha256(file: File): String {
    val digest = MessageDigest.getInstance("SHA-256")
    file.inputStream().use { input ->
        val buffer = ByteArray(1 shl 16)
        while (true) {
            val count = input.read(buffer)
            if (count < 0) break
            digest.update(buffer, 0, count)
        }
    }
    return digest.digest().joinToString("") { "%02x".format(it) }
}

val verifyRuntimeA15 = tasks.register("verifyRuntimeA15") {
    doLast {
        if (providers.gradleProperty("ciSkipNativeVerify").isPresent) return@doLast
        val manifest = runtimeRoot.resolve("assets/guest-runtime-a15-inputs.json")
        check(manifest.isFile) {
            "missing Android 15 runtime inputs: $manifest\n" +
                    "run: python guest-runtime-a15/scripts/prepare-a15.py\n" +
                    "or:  ./gradlew :guest-runtime-a15:prepareA15Runtime\n" +
                    "or:  -PguestRuntimeA15Prepared=<prepared dir>"
        }
        val json = JsonSlurper().parse(manifest) as Map<*, *>
        check((json["guestSdk"] as Number).toInt() == 35) { "guestSdk must be 35" }
        check((json["frameworkSdk"] as Number).toInt() == 35) { "frameworkSdk must be 35" }
        val roles = json["platformLibraries"] as? Map<*, *>
        check(roles != null) { "platformLibraries is required" }
        for (role in listOf("propertyClient", "guestDevices", "binderDevices",
            "guestLog", "managerPolicy", "binderCore", "halModules")) {
            check(roles!![role] is String) { "platformLibraries.$role is required" }
        }
        val files = json["files"] as List<*>
        check(files.isNotEmpty()) { "No native files in the A15 manifest" }
        var checked = 0
        for (item in files) {
            val entry = item as Map<*, *>
            val logical = entry["logical"] as String
            val source = entry["source"] as String
            check(source in setOf("redroid15", "aosp15", "project-a15")) {
                "Unexpected source '$source' for $logical"
            }
            for (foreign in listOf("liba10vm-", "liba10", "liba9vm-", "liba9")) {
                check(!logical.startsWith(foreign)) {
                    "Foreign runtime logical name in A15 prepared: $logical"
                }
            }
            // 客体 .so 的位置由清单自己说（files[].libPath）：
            //   旧格式（打进 APK）-> assets/guest-runtime-a15/lib/<name>
            //   新格式（ROM 包）  -> payload/lib/<name>（那一份不经过 Gradle）
            // 没有 libPath 的清单就是老行为（APK 的 lib/），只允许历史产物这么写。
            // resident=true 的是被 execve 的那几个（linker / GPU 端点 / 属性播种器）：
            // untrusted_app 不能从 app_data_file 执行，它们必须留在 APK 的 lib/ 里。
            val libPath = entry["libPath"] as? String
            val isResident = (entry["resident"] as? Boolean) == true
            val file = if (isResident || libPath == null) runtimeRoot.resolve("jniLibs/arm64-v8a/" + entry["name"])
                       else runtimeRoot.resolve("assets/" + libPath)
            check(file.isFile) {
                "Missing A15 native input: $file\n" +
                        (if (libPath == null)
                            "这份 prepared 还是老布局（.so 在 jniLibs/）。跑 " +
                                    "python guest-runtime-a15/rom/stage-apk-payload.py 生成 prepared-apk。"
                        else "prepared-apk 不完整，重跑 rom/stage-apk-payload.py。")
            }
            check(file.length() == (entry["bytes"] as Number).toLong()) {
                "Size mismatch for $logical"
            }
            check(sha256(file) == entry["sha256"]) { "SHA-256 mismatch for $logical" }
            checked += 1
        }
        // 硬闸门：APK 的 lib/ 里只允许 resident 那几个客体文件（docs/rom-package/04 §4）。
        val jniDir = runtimeRoot.resolve("jniLibs/arm64-v8a")
        val allowed = files.map { (it as Map<*, *>) }
            .filter { (it["resident"] as? Boolean) == true }
            .map { it["name"] as String }
            .toSet()
        val present = jniDir.listFiles { f -> f.isFile && f.name.endsWith(".so") }
            ?.map { it.name }?.toSet() ?: emptySet<String>()
        check(present == allowed) {
            "APK 的 lib/arm64-v8a 内容与 resident 清单不一致：" +
                    "\n  多出来（不该在 APK 里）：" + (present - allowed) +
                    "\n  缺少（必须在 APK 里，execve 只能从这里）：" + (allowed - present) +
                    "\n修法：重跑 python guest-runtime-a15/rom/stage-apk-payload.py"
        }
        logger.lifecycle("A15 runtime verified: $checked native files (payload layout)")
    }
}
tasks.named("preBuild").configure { dependsOn(verifyRuntimeA15) }

// Explicit regeneration of the prepared tree. It is not wired into preBuild
// because it rewrites >1 GB of assets and needs Python + JDK + d8.
val prepareA15Runtime = tasks.register<Exec>("prepareA15Runtime") {
    group = "android15"
    description = "Regenerate guest-runtime-a15/prepared from the Redroid 15 rootfs"
    workingDir = projectDir
    commandLine("python", projectDir.resolve("scripts/prepare-a15.py").absolutePath)
}

tasks.withType<org.gradle.api.tasks.bundling.Zip>().configureEach { isZip64 = true }

// AGP 9 的官方目录注入点：按 variant 添加"静态源码目录"，等价于旧 sourceSets 的
// jniLibs.srcDir / assets.srcDir，且不经过已废弃的 com.android.build.gradle.api.* 类型。
androidComponents {
    onVariants { variant ->
        variant.sources.jniLibs?.addStaticSourceDirectory(runtimeRoot.resolve("jniLibs").absolutePath)
        variant.sources.assets?.addStaticSourceDirectory(runtimeRoot.resolve("assets").absolutePath)
    }
}
